using System;using System.IO;using System.Drawing;using Forms=System.Windows.Forms;
public sealed class ManagerTray:IDisposable {
 readonly Font menuFont=new Font("Segoe UI",9f);bool? styledLight;readonly Forms.NotifyIcon manager,second;readonly Icon mainIcon,secondIcon;
 static Icon Load(string path){using(var stream=new MemoryStream(File.ReadAllBytes(path)))using(var icon=new Icon(stream))return (Icon)icon.Clone();}
 public ManagerTray(Action show,Action open,Action quit,Action exit){mainIcon=Load(Path.Combine(Engine.Home,@"Assets\dual-steam.ico"));secondIcon=Load(Path.Combine(Engine.Home,@"Assets\second-steam.ico"));manager=new Forms.NotifyIcon{Icon=mainIcon,Text="Dual Steam",Visible=true};var menu=new Forms.ContextMenuStrip();menu.Items.Add("Open Dual Steam",null,(s,e)=>show());menu.Items.Add("Open Second Steam",null,(s,e)=>open());menu.Items.Add("Exit manager",null,(s,e)=>exit());manager.ContextMenuStrip=menu;manager.DoubleClick+=(s,e)=>show();second=new Forms.NotifyIcon{Icon=secondIcon,Text="Second Steam"};menu=new Forms.ContextMenuStrip();menu.Items.Add("Open Second Steam",null,(s,e)=>open());menu.Items.Add("Quit Second Steam",null,(s,e)=>quit());menu.Items.Add("Open Dual Steam",null,(s,e)=>show());second.ContextMenuStrip=menu;second.DoubleClick+=(s,e)=>open();manager.ContextMenuStrip.Opening+=(s,e)=>Style(manager.ContextMenuStrip);second.ContextMenuStrip.Opening+=(s,e)=>Style(second.ContextMenuStrip);Style(manager.ContextMenuStrip);Style(second.ContextMenuStrip);styledLight=DualSteam.UI.Theme.Light;}
 void Style(Forms.ContextMenuStrip menu){bool light=DualSteam.UI.Theme.Light;menu.Renderer=new Forms.ToolStripProfessionalRenderer(new TrayColors(light));menu.BackColor=light?Color.FromArgb(255,255,255):Color.FromArgb(30,32,36);menu.ForeColor=light?Color.FromArgb(27,28,34):Color.FromArgb(242,243,245);menu.Font=menuFont;menu.ShowImageMargin=false;menu.Padding=new Forms.Padding(5);foreach(Forms.ToolStripItem item in menu.Items){item.ForeColor=menu.ForeColor;item.Padding=new Forms.Padding(8,5,8,5);}}
 public void Update(bool running){second.Visible=Preferences.Current.SecondTray&&running;bool light=DualSteam.UI.Theme.Light;if(styledLight!=light){Style(manager.ContextMenuStrip);Style(second.ContextMenuStrip);styledLight=light;}}
 public void Dispose(){manager.Visible=false;second.Visible=false;manager.Dispose();second.Dispose();mainIcon.Dispose();secondIcon.Dispose();menuFont.Dispose();}
}
